// Junta todos os itens de entrada em UM único objeto:
// { unidade, parametros, dados: { devolucao_pedidos: [...], total_pendente: [...], ... } }

const inputs = $input.all();

let unidade = $('unidade').first().json.unidade;
let parametros = null;
const dados = {};

for (const { json } of inputs) {
  for (const [k, v] of Object.entries(json)) {
    if (k === 'unidade') {
      unidade = v;
    } else if (k === 'parametros') {
      parametros = v;
    } else {
      // k é o nome do dataset (ex.: devolucao_pedidos, total_pendente, descontos_titulos, etc.)
      dados[k] = v;
    }
  }
}

// fallback de parâmetros caso não venham de um Set
if (!parametros) {
  parametros = { dias_limite_devolucao: 30, categoria_critica: 'TEMPERADO' };
}

return [
  {
    json: {
      unidade,
      parametros,
      dados
    }
  }
];
